public class User {
    private Integer id;
    private String name;
    private LocalDate birthday;
    private String nickName;
    private Gender gender;
    private String avatarAddress;
    ...
}

@Service
public class UserService {
    @Autowired
    private JooqTemplate jt;
    public int insertUser(User user) {
        //Bean to camel map
        Map values=JooqMaps.toCamelCase(user);
        //Add additional data
        values.put("create_time", LocalDateTime.now());
        // Insert record
        return jt.insertReturningv("user_table",values,"id").get("id",…
